from pathlib import Path
import subprocess,base64,json
s=r'''$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root='C:\Users\Administrator\WorkSpace\muxigame\bmc5server\config\yes_steve_model\custom';$rows=@();foreach($category in @('11_umamusume_player','10_umamusume')){Get-ChildItem -LiteralPath (Join-Path $root $category) -File -Recurse|ForEach-Object{$rows+=@{path=$_.FullName;relative=$_.FullName.Substring($root.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower();bytes=$_.Length}}};@{root=$root;files=$rows}|ConvertTo-Json -Depth 5 -Compress'''
s=s.replace('@{root=$root;files=$rows}', "@{root=$root;files=$rows;legacyConfigs=@(Get-ChildItem -LiteralPath (Join-Path $root '10_umamusume') -Filter ysm.json -Recurse -File|ForEach-Object{$c=Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8|ConvertFrom-Json;@{path=$_.FullName;name=$c.metadata.name;properties=$c.properties}})}")
w='& ([scriptblock]::Create([Console]::In.ReadToEnd()))'
p=subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=8','administrator@<PRIVATE_HOST>','powershell','-NoProfile','-NonInteractive','-EncodedCommand',base64.b64encode(w.encode('utf-16-le')).decode()],input=s.encode('utf-8'),capture_output=True,timeout=55)
assert p.returncode==0,p.stderr.decode(errors='replace')
r=json.loads(p.stdout.decode('utf-8-sig')); a=json.loads(Path('cover-readonly-audit/public-audit.json').read_text(encoding='utf-8')); expect={f['path'].split('/custom/')[1]:f['sha256'] for f in a['files']}; new=[f for f in r['files'] if f['relative'].startswith('11_umamusume_player/')];r['newFiles']=len(new);r['newFilesAllMatchPublic']=len(new)==len(expect) and all(expect.get(f['relative'])==f['sha256'] for f in new)
Path('cover-readonly-audit/server-audit.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({k:v for k,v in r.items() if k!='files'}))
